import{_ as a,c as n,o as i,ag as t}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"AI-assisted bug fix and feature project","description":"","frontmatter":{},"headers":[],"relativePath":"practice/engineering/ai-engineering/development-project.md","filePath":"practice/engineering/ai-engineering/development-project.md"}'),r={name:"practice/engineering/ai-engineering/development-project.md"};function o(s,e,d,c,l,p){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="ai-assisted-bug-fix-and-feature-project" tabindex="-1">AI-assisted bug fix and feature project <a class="header-anchor" href="#ai-assisted-bug-fix-and-feature-project" aria-label="Permalink to “AI-assisted bug fix and feature project”">​</a></h1><p>Use <a href="./../../../ai-assisted-engineering/">AI for Software Development</a> with a small owned TypeScript catalogue. <strong>All learner work remains outstanding.</strong> You may use the worked catalogue after predicting behavior, but copied reference test results do not establish your own investigation.</p><h2 id="dev-01-reproduce-and-fix-mutation" tabindex="-1"><span class="hub-section-number">1 </span>DEV-01: reproduce and fix mutation <a class="header-anchor" href="#dev-01-reproduce-and-fix-mutation" aria-label="Permalink to “1 DEV-01: reproduce and fix mutation”">​</a></h2><p>Create a disposable baseline whose sorter changes its input array. Define the non-mutation and title/ID ordering contract, obtain actual failing evidence, fix it and run focused checks plus build/test. Ask an assistant to investigate, then inspect its proposed change yourself. Retain one meaningful challenge, such as a frozen caller array or duplicate titles.</p><h2 id="dev-02-develop-query-and-limit" tabindex="-1"><span class="hub-section-number">2 </span>DEV-02: develop query and limit <a class="header-anchor" href="#dev-02-develop-query-and-limit" aria-label="Permalink to “2 DEV-02: develop query and limit”">​</a></h2><p>Add the <a href="./../../../ai-assisted-engineering/feature-development.html">declared feature contract</a>: trimmed case-insensitive substring query, sort before limit, default ten, explicit zero and integer range 0–50. Map each criterion to a check. Keep invalid/no-match/tie cases, actual build/test output and one failed candidate/correction. No model or database is needed for the helper.</p><h2 id="dev-03-diagnose-and-review" tabindex="-1"><span class="hub-section-number">3 </span>DEV-03: diagnose and review <a class="header-anchor" href="#dev-03-diagnose-and-review" aria-label="Permalink to “3 DEV-03: diagnose and review”">​</a></h2><p>Introduce a meaningful fault only in your disposable copy, confirm a requirement-derived check detects it, then restore your owned candidate. Classify one environment/build failure without changing correct production behavior merely to silence it. Review the final diff and new files against the task; retain actual findings or an honestly limited no-findings result.</p><h2 id="dev-04-prepare-a-local-handoff" tabindex="-1"><span class="hub-section-number">4 </span>DEV-04: prepare a local handoff <a class="header-anchor" href="#dev-04-prepare-a-local-handoff" aria-label="Permalink to “4 DEV-04: prepare a local handoff”">​</a></h2><p>Prepare separate bug-fix and feature PR summaries with trigger/new behavior, actual checks and limits. Save the candidate/diff and acceptance map. Do not claim remote CI, publication or independent approval. Never push: only the user may push in this repository.</p><h2 id="dev-05-reuse-and-optional-coordination" tabindex="-1"><span class="hub-section-number">5 </span>DEV-05: reuse and optional coordination <a class="header-anchor" href="#dev-05-reuse-and-optional-coordination" aria-label="Permalink to “5 DEV-05: reuse and optional coordination”">​</a></h2><p>Run the same inspect→reproduce→implement→verify→review→handoff process on another small issue. Record what the runbook needed to change. Optionally request an independent read-only review of a frozen candidate; record who/what reviewed which revision. Multiple agents and worktrees are optional, not required for completion.</p><p>These increments support <a href="./../../ai-project.html#p-336">P-336</a> rather than replacing its evidence requirements. The <a href="./../../../workbench/engineering/ai-engineering/catalogue/">catalogue source/checks</a> and existing retry case are separate worked references. Preserve Autocode templates and restricted tests; run the applicable official checks when this is a real course submission.</p>',13)])])}const f=a(r,[["render",o]]);export{h as __pageData,f as default};
